// src7/plugins/programs/Protocol.ts
 164  function parseReady(line: string, spec: ProgramSpec): ReadyLine | undefined {
 165    let decoded: unknown;
 166    try {
 167      decoded = JSON.parse(line);
 168    } catch {
 169      return undefined;
 170    }
 171    if (typeof decoded !== 'object' || decoded === null) return undefined;
 172  
 173    const raw = decoded as Record<string, unknown>;
 174    const protocol = raw['jmbots'];
 175    if (typeof protocol !== 'number') return undefined;
 176  
 177    //G 版本不兼容时阻止自动重试，等用户换正确的程序。
 178    if (protocol !== PROTOCOL) {
 179      throw new UnsupportedProtocol(`协议版本不对（程序 ${String(protocol)}，jmbots 支持 ${String(PROTOCOL)}）`);
 180    }
 181    if (raw['event'] !== 'ready' || raw['name'] !== spec.name) {
 182      throw new Error(`就绪行的事件或程序名和 ${spec.name} 不符`);
 183    }
 184    const version = raw['version'];
 185    if (typeof version !== 'string' || version.trim() === '') throw new Error('就绪行缺少程序版本');
 186  
 187    const port = raw['port'];
 188    if (typeof port !== 'number' || !Number.isInteger(port) || port < 1 || port > 65535) {
 189      throw new Error('就绪行端口要是 1 至 65535 的整数');
 190    }
 191    if (spec.port !== 0 && port !== spec.port) throw new Error(`就绪行端口与配置 ${String(spec.port)} 不符`);
 192  
 193    return { version, port };
 194  }
```

### 解释
- Host L427：`waitReady` 等就绪行，超过 `startup_ms` 就算启动失败。
- Protocol L174–L180：协议版本不对抛 `UnsupportedProtocol`，状态改 blocked，不再自动重试。
- Protocol L181–L191：
  - 事件不是 ready、名字不符，抛错；
  - 缺版本，抛错；
  - 端口不合法，或和配置的固定端口不同，抛错。

