// src7/plugins/programs/Protocol.ts
 244  export async function readReport(
 245    url: string, name: string, route: 'info' | 'health', timeoutMs: number, signal: AbortSignal,
 246  ): Promise<ProgramReport | undefined> {
 247    const endpoint = `${url}/jmbots/v1/${route}`;
 248    const timeout = AbortSignal.timeout(timeoutMs);
 249    const until = AbortSignal.any([signal, timeout]);
 250    const options: RequestInit = { signal: until, redirect: 'error' };
 251    try {
 252      //M 只信已核对协议与程序名的回执，不让错误服务提供资源排行或暂停能力。
 253      const response = await fetch(endpoint, options);
 254      const decoded: unknown = await response.json();
 255      if (!response.ok || typeof decoded !== 'object' || decoded === null) return undefined;
 256  
 257      const raw = decoded as Record<string, unknown>;
 258      if (raw['ok'] !== true || raw['protocol'] !== PROTOCOL || raw['name'] !== name) return undefined;
 259  
 260      const capabilities = raw['capabilities'];
 261      const pause = Array.isArray(capabilities) && capabilities.includes('pause');
 262      let rssMb: number | undefined;
 263      const rss = raw['rssMb'];
 264      if (typeof rss === 'number' && Number.isFinite(rss) && rss >= 0) {
 265        rssMb = rss;
 266      }
 267      //M 界面只接受程序内部路径，不接受任意主机、端口或脚本URL。
 268      const ui = getUiPath(raw['ui']);
 269      return { pause, rssMb, ui };
 270    } catch {
 271      return undefined;
 272    }
 273  }
```

