 501    /** 定期核对活着的程序，达连续失败阈值后交给监督任务重启。 */
 502    private async watchHealth(endpoint: string, signal: AbortSignal): Promise<void> {
 503      let misses = 0;
 504      let licenseAt = Date.now();
 505      const wait = { signal };
 506      while (!signal.aborted) {
 507        await timers.setTimeout(this.timing.watchMs, undefined, wait);
 508  
 509        //M 独立探测健康接口，连接失败与身份不符都算一次失败。
 510        const report = await protocolModule.readReport(
 511          endpoint, this.spec.name, 'health', this.timing.healthMs, signal,
 512        );
 513        signal.throwIfAborted();
 514        if (report !== undefined) {
 515          this.rssMb = report.rssMb;
 516          this.rssAt = Date.now();
 517          if (Date.now() - licenseAt >= 60_000) {
 518            //M 每分钟更新一次授权，缺接口或失败保持未知，不把未知当未授权。
 519            this.license = await protocolModule.readLicense(endpoint, signal);
 520            signal.throwIfAborted();
 521            licenseAt = Date.now();
 522            //M 授权状态变化单独广播，不把授权到期当停机。
 523            this.publishState();
 524          }
 525          misses = 0;
 526          this.note = '在运行';
 527          continue;
 528        }
 529        misses += 1;
 530        this.note = `健康检查连续失败 ${String(misses)} 次`;
 531        if (misses >= this.timing.healthMisses) {
 532          this.state = 'unhealthy';
 533          //M 健康异常不再提供ready入口，后续正常停止/重试由监督处理。
 534          this.publishState();
 535          return;
 536        }
 537      }
 538    }
